uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float evoType;
uniform float spreadType;
uniform float shape;
uniform float colorMode;
uniform float beatSrc;
uniform float revEvo;
uniform float autop;
uniform float autoSpeed;
uniform float progress;
uniform float count;
uniform float size;
layout(color) uniform half4 colA;
layout(color) uniform half4 colB;
uniform float hueSpeed;
layout(color) uniform half4 bgCol;
uniform float scale;
uniform float angle;
uniform float2 position;
uniform float2 stretch;
uniform float alpha;
uniform float blendMode;
uniform float alphaComp;
uniform float audioLevel;
uniform float bass;
uniform float mid;
uniform float high;
uniform float audio_level;
uniform float threshold;
uniform float curve;
uniform float beatRush;
uniform float sizePunch;
uniform float pushDist;
uniform float glowPunch;
uniform float brightPunch;
uniform float life;
uniform float lifeVar;
uniform float speed;
uniform float speedVar;
uniform float sizeVar;
uniform float shrink;
uniform float fadeIn;
uniform float fadeOut;
uniform float spin;
uniform float seed;
uniform float spreadW;
uniform float spreadH;
uniform float ringR;
uniform float emitDir;
uniform float coneAngle;
uniform float gravity;
uniform float wind;
uniform float turb;
uniform float turbFreq;
uniform float glow;
uniform float brightness;
uniform float overdrawOn;
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float2 nmStd(float2 p, float pxs) {
        float z = max(scale * 2.0, 0.002);
        p -= position * pxs;
        p = nmRot(p, -radians(angle));
        return p / (z * max(stretch, float2(0.01)));
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx, 0.0, 1.0) * clamp(alpha, 0.0, 1.0);
        float4 b = tex * clamp(alphaComp, 0.0, 1.0);
        float4 o;
        if (int(blendMode) == 0) o = f;
        else if (int(blendMode) == 1) o = float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        else if (int(blendMode) == 2) o = float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        else if (int(blendMode) == 4) o = float4(b.rgb + f.rgb, max(b.a, f.a));
        else o = f + b * (1.0 - f.a);
        o = clamp(o, 0.0, 1.0);
        return float4(min(o.rgb, float3(o.a)), o.a);
    }
    float h1(float a, float b) { return fract(sin(a * 127.1 + b * 311.7 + seed * 7.31) * 43758.5453); }
    float3 hue2rgb(float h) { return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
    float sdStar(float2 p, float r) {
        float a = atan(p.y, p.x);
        float rr = r * (0.42 + 0.58 * pow(abs(cos(2.5 * a)), 5.0));
        return (length(p) - rr) * 0.75;
    }
    void amzRender() {
        float4 lay = amzTexture(0, amzScreenNorm());
        float2 L = layer;
        float2 p = (amzLayerNorm() - 0.5) * L;
        p = nmStd(float2(p.x, -p.y), 1.0);
        p.y = -p.y;
        float lv = int(beatSrc) == 1 ? bass : (int(beatSrc) == 2 ? mid : (int(beatSrc) == 3 ? high : audioLevel));
        float th = clamp(threshold, 0.0, 0.95);
        float drive = pow(clamp((lv - th) / (1.0 - th), 0.0, 1.0), max(curve, 0.05));
        float T = progress * 10.0 + ((autop>0.5) ? time * autoSpeed : 0.0) + audio_level * beatRush;
        float px = 1.0;
        float N = max(floor(count + 0.5), 1.0);
        float brightF = 1.0 + brightPunch * drive;
        float sizeF = 1.0 + sizePunch * drive;
        float pushF = pushDist * drive;
        float glowF = glow * (1.0 + glowPunch * drive);
        float dirA = radians(emitDir);
        float4 acc = float4(0.0);
        for (int ii = 0; ii < 300; ii++) {
            float i = float(ii);
            if (i >= N) break;
            float lf = max(life, 0.05) * (1.0 + (h1(i, 1.0) - 0.5) * lifeVar);
            float tt = T + h1(i, 2.0) * lf;
            float cyc = floor(tt / lf);
            float age = tt - cyc * lf;
            if ((revEvo>0.5)) age = lf - age;
            float u = age / lf;
            float k = i * 13.0 + cyc * 7.77;
            float r1 = h1(k, 3.0), r2 = h1(k, 4.0), r3 = h1(i, 5.0), r4 = h1(i, 6.0);
            float spd = speed * (1.0 + (h1(k, 7.0) - 0.5) * 2.0 * speedVar);
            float2 s = float2(0.0);
            float2 radial = float2(cos(r1 * 6.2831853), sin(r1 * 6.2831853));
            if (int(spreadType) == 1) s = nmRot(float2((r1 - 0.5) * spreadW * L.x, 0.0), dirA - 1.5707963);
            else if (int(spreadType) == 2) s = radial * ringR * min(L.x, L.y);
            else if (int(spreadType) == 3) s = radial * sqrt(r2) * ringR * min(L.x, L.y);
            else if (int(spreadType) == 4) s = float2((r1 - 0.5) * spreadW * L.x, (r2 - 0.5) * spreadH * L.y);
            else if (int(spreadType) == 5) s = float2((r1 - 0.5) * L.x, (r2 - 0.5) * L.y);
            float ca = dirA + (h1(k, 8.0) - 0.5) * radians(coneAngle);
            float2 cone = float2(cos(ca), sin(ca));
            float2 wob = float2(sin(age * turbFreq * 2.1 + r3 * 6.2831853), cos(age * turbFreq * 1.7 + r4 * 6.2831853)) * turb;
            float2 q;
            float tw = 1.0;
            if (int(evoType) <= 1) {
                float2 gd = int(evoType) == 1 ? float2(0.0, -1.0) : -float2(cos(dirA), sin(dirA));
                float2 gn = float2(-gd.y, gd.x);
                float2 st = s - gd * spd * lf * 0.5 * step(4.5, float(int(spreadType)));
                q = st + gd * spd * age + gn * wob.x;
            }
            else if (int(evoType) == 2) {
                float2 dv = length(s) > 1.0 ? normalize(s) : (coneAngle >= 359.0 ? radial : cone);
                q = s + dv * spd * lf * (1.0 - exp(-3.0 * u)) / 3.0 + wob * u;
            } else if (int(evoType) == 3) q = s + cone * spd * age - float2(0.0, 0.5 * (abs(gravity) + spd * 1.5) * age * age) + wob * u;
            else if (int(evoType) == 4) {
                float rad = max(length(s), ringR * min(L.x, L.y) * (0.3 + 0.7 * r2));
                float a0 = atan(s.y, s.x + 1e-5) + spd / max(rad, 1.0) * age;
                q = float2(cos(a0), sin(a0)) * rad + wob * 0.3;
            } else if (int(evoType) == 5) {
                float rad = max(length(s), ringR * min(L.x, L.y)) * (1.0 - u);
                float a0 = atan(s.y, s.x + 1e-5) + spd / max(rad + 20.0, 1.0) * age;
                q = float2(cos(a0), sin(a0)) * rad;
            } else if (int(evoType) == 8) {
                float z = 1.0 - u;
                float persp = 0.35 / (z + 0.12);
                float r0 = ringR * min(L.x, L.y) * (0.45 + 0.55 * r2);
                float2 lane = int(spreadType) == 0 ? float2(cos(r1 * 6.2831853), sin(r1 * 6.2831853)) * r0 * 2.5
                          : (int(spreadType) == 2 || int(spreadType) == 3 ? s * 2.5 : s);
                q = lane * persp + wob * 0.2 * persp;
                tw = persp;
            } else if (int(evoType) == 6) q = s + wob * 2.0 + float2(sin(age * 0.7 + r3 * 9.0), cos(age * 0.5 + r4 * 9.0)) * spd * 0.3;
            else { q = s + wob * 0.2; tw = 0.5 + 0.5 * sin(age * (2.0 + r3 * 4.0) * turbFreq + r4 * 6.2831853); }
            if (int(evoType) <= 2 || int(evoType) == 6) q += float2(wind * age, -0.5 * gravity * age * age);
            else if (int(evoType) == 3) q += float2(wind * age, 0.0);
            if (pushF > 0.0 && length(q) > 0.5) q += normalize(q) * pushF;
            float sz = size * (1.0 + (r3 - 0.5) * 2.0 * sizeVar) * sizeF * mix(1.0, 1.0 - u, shrink);
            if (int(evoType) == 8) { float nz = u; sz *= 0.45 + 0.9 * nz; tw = smoothstep(0.05, 0.45, nz) * (1.0 - smoothstep(0.9, 1.0, nz)); }
            sz = max(sz, 0.3);
            float fa = smoothstep(0.0, max(fadeIn, 0.001), u) * (1.0 - smoothstep(1.0 - max(fadeOut, 0.001), 1.0, u)) * tw;
            float2 d = p - q;
            if (abs(d.x) > sz * 6.0 + 4.0 || abs(d.y) > sz * 6.0 + 4.0) continue;
            float2 dr = nmRot(d, -radians(spin) * age - r4 * 6.2831853);
            float sd;
            if (int(shape) == 2) { float2 b = abs(dr) - float2(sz * 0.8); sd = length(max(b, 0.0)) + min(max(b.x, b.y), 0.0); }
            else if (int(shape) == 3) sd = sdStar(dr, sz * 1.2);
            else if (int(shape) == 4) sd = abs(length(d) - sz * 0.8) - sz * 0.18;
            else if (int(shape) == 5) {
                float sa = int(evoType) == 2 ? atan(q.y - s.y, q.x - s.x + 1e-5) : (int(evoType) == 1 ? -1.5707963 : (int(evoType) == 0 ? dirA + 3.14159265 : (int(evoType) == 8 ? atan(q.y, q.x + 1e-5) : ca)));
                float2 ds = nmRot(d, -sa);
                ds.x = max(abs(ds.x) - sz * 2.0, 0.0);
                sd = length(ds) - sz * 0.25;
            } else if (int(shape) == 7) {
                float2 hp = dr / (sz * 1.7) + float2(0.0, 0.5);
                hp.x = abs(hp.x);
                float hd;
                if (hp.y + hp.x > 1.0) hd = length(hp - float2(0.25, 0.75)) - 0.35355339;
                else hd = sqrt(min(dot(hp - float2(0.0, 1.0), hp - float2(0.0, 1.0)), dot(hp - 0.5 * max(hp.x + hp.y, 0.0), hp - 0.5 * max(hp.x + hp.y, 0.0)))) * sign(hp.x - hp.y);
                sd = hd * sz * 1.7;
            } else if (int(shape) == 8) sd = (abs(dr.x) + abs(dr.y) * 0.7 - sz) * 0.7;
            else if (int(shape) == 9) {
                float2 tp = dr / sz;
                const float k3 = 1.7320508;
                tp.x = abs(tp.x) - 1.0; tp.y = tp.y + 1.0 / k3;
                if (tp.x + k3 * tp.y > 0.0) tp = float2(tp.x - k3 * tp.y, -k3 * tp.x - tp.y) / 2.0;
                tp.x -= clamp(tp.x, -2.0, 0.0);
                sd = -length(tp) * sign(tp.y) * sz;
            } else if (int(shape) == 10) {
                float2 ap = abs(dr);
                float2 b1 = ap - float2(sz, sz * 0.3), b2 = ap - float2(sz * 0.3, sz);
                sd = min(length(max(b1, 0.0)) + min(max(b1.x, b1.y), 0.0), length(max(b2, 0.0)) + min(max(b2.x, b2.y), 0.0));
            } else if (int(shape) == 11) {
                float3 kh = float3(-0.8660254, 0.5, 0.57735027);
                float2 hx = abs(dr);
                hx -= 2.0 * min(dot(kh.xy, hx), 0.0) * kh.xy;
                hx -= float2(clamp(hx.x, -kh.z * sz * 0.9, kh.z * sz * 0.9), sz * 0.9);
                sd = length(hx) * sign(hx.y);
            } else sd = length(d) - sz * (int(shape) == 0 ? 0.35 : 1.0);
            float core = 1.0 - smoothstep(-px, px, sd);
            float halo = glowF * exp(-max(sd, 0.0) / max(sz * (int(shape) == 0 ? 0.9 : 0.6), 0.5)) * (int(shape) == 0 ? 1.0 : 0.6);
            float v = clamp(core + halo, 0.0, 1.5) * fa;
            if (v <= 0.001) continue;
            float3 col;
            if (int(colorMode) == 0) col = colA.rgb;
            else if (int(colorMode) == 1) col = mix(colA.rgb, colB.rgb, u);
            else if (int(colorMode) == 2) col = mix(colA.rgb, colB.rgb, 0.5 + 0.5 * sin(6.2831853 * (T * hueSpeed + r4)));
            else col = hue2rgb(fract(r4 + u * 0.25));
            acc.rgb += col * v * brightness * brightF;
            acc.a += min(v, 1.0);
        }
        acc.a = clamp(acc.a, 0.0, 1.0);
        acc.rgb = min(acc.rgb, float3(max(acc.a, 0.0001)) * 1.0);
        float4 bg = float4(bgCol.rgb * bgCol.a, bgCol.a);
        acc += bg * (1.0 - acc.a);
        amzOutput = nmBlend(lay, acc);
        if (!(overdrawOn>0.5)) amzOutput *= lay.a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
